import * as React from "react";
import { GLCanvas, type FrameCtx } from "@/lib/glcanvas";

/** Haze - low drifting fog or mist that thickens toward the bottom edge. Transparent. Use under content or as a footer. */
const FRAG = `
precision highp float;
uniform vec2 uRes; uniform float uTime, uCover, uSeed; uniform vec3 uTint;
float hash(vec3 p){ p=fract(p*0.3183099+0.1); p*=17.0; return fract(p.x*p.y*p.z*(p.x+p.y+p.z)); }
float noise(vec3 x){ vec3 i=floor(x),f=fract(x); f=f*f*(3.0-2.0*f);
  return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),
             mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z); }
float fbm(vec3 p){ float a=0.5,s=0.0; for(int i=0;i<5;i++){ s+=a*noise(p); p=p*2.02+vec3(3.1,1.7,5.3); a*=0.5; } return s; }
void main(){
  vec2 e=gl_FragCoord.xy/uRes; float asp=uRes.x/uRes.y;
  float acc=0.0;
  // three depth layers drifting at different speeds, thicker at the bottom
  for(int i=0;i<3;i++){
    float fi=float(i); float sp=0.05+0.04*fi; float sc=1.4+fi*1.1;
    vec3 p=vec3(e.x*asp*sc-uTime*sp,e.y*sc*1.6,uTime*0.03+fi*4.0+uSeed*3.0);
    float n=fbm(p);
    float h=smoothstep(1.0,0.0,e.y+0.18*fi*(0.0));
    float layer=smoothstep(mix(0.62,0.35,uCover),0.8,n)*pow(h,1.0+fi*0.4);
    acc+=layer*(0.55-0.12*fi);
  }
  acc=clamp(acc,0.0,1.0);
  acc*=smoothstep(0.0,0.08,e.x)*smoothstep(1.0,0.92,e.x);
  vec3 col=mix(vec3(0.72,0.78,0.88),vec3(0.97,0.98,1.0),acc)*uTint;
  gl_FragColor=vec4(col*acc,acc);
}`;
export interface HazeProps extends React.HTMLAttributes<HTMLDivElement> {
  coverage?: number; speed?: number; seed?: number; tint?: [number, number, number]; /** "white" for dark or sky surfaces, "slate" for light surfaces */ tone?: "white" | "slate"; quality?: number; time?: number;
}
export function Haze({ coverage = 0.55, speed = 1, seed = 0, tone = "white", tint = tone === "slate" ? [0.5, 0.57, 0.72] : [1, 1, 1], quality = 0.55, time, style, ...rest }: HazeProps) {
  const cfg = React.useRef({ coverage, seed, tint }); cfg.current = { coverage, seed, tint };
  const onFrame = React.useCallback(({ gl, U, t, w, h }: FrameCtx) => {
    const c = cfg.current;
    gl.uniform2f(U.uRes, w, h); gl.uniform1f(U.uTime, t * 4); gl.uniform1f(U.uCover, c.coverage);
    gl.uniform1f(U.uSeed, c.seed); gl.uniform3fv(U.uTint, c.tint);
  }, []);
  return <GLCanvas {...rest} frag={FRAG} uniforms={["uRes","uTime","uCover","uSeed","uTint"]} speed={speed} quality={quality} time={time}
    onFrame={onFrame} redrawKey={[coverage, seed, tint]} style={{ display: "block", width: "100%", height: 220, ...style }} />;
                                             }

import * as React from "react";

const VERT = `attribute vec2 p; void main(){ gl_Position = vec4(p,0.,1.); }`;

export interface FrameCtx {
  gl: WebGLRenderingContext;
  U: Record<string, WebGLUniformLocation | null>;
  /** seconds of animation (scaled by speed) or the fixed time */
  t: number;
  w: number;
  h: number;
  /** accumulated drag in radians */
  dyaw: number;
  dpitch: number;
  fixed: boolean;
}

export interface GLCanvasProps extends React.HTMLAttributes<HTMLDivElement> {
  frag: string;
  uniforms: string[];
  speed: number;
  quality: number;
  /** fixed time in seconds for stills; disables animation */
  time?: number;
  interactive?: boolean;
  /** sets uniforms every frame */
  onFrame: (c: FrameCtx) => void;
  /** change to force a redraw in static mode */
  redrawKey?: unknown;
  /** z-order of the canvas: -1 puts it behind children */
  behind?: boolean;
}

/** Shared WebGL plumbing: context, fullscreen triangle, resize, pause offscreen, reduced motion, drag. */
export function GLCanvas({ frag, uniforms, speed, quality, time, interactive, onFrame, redrawKey, behind, style, children, ...rest }: GLCanvasProps) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const live = React.useRef({ speed, quality, time, onFrame });
  live.current = { speed, quality, time, onFrame };
  const drag = React.useRef({ x: 0, y: 0, down: false, dyaw: 0, dpitch: 0 });
  const [failed, setFailed] = React.useState(false);

  React.useEffect(() => {
    const canvas = canvasRef.current!;
    const gl = canvas.getContext("webgl", { premultipliedAlpha: true, alpha: true, antialias: false });
    if (!gl) { setFailed(true); return; }
    const mk = (type: number, src: string) => {
      const s = gl.createShader(type)!; gl.shaderSource(s, src); gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s) || "shader");
      return s;
    };
    let prog: WebGLProgram;
    try {
      prog = gl.createProgram()!;
      gl.attachShader(prog, mk(gl.VERTEX_SHADER, VERT));
      gl.attachShader(prog, mk(gl.FRAGMENT_SHADER, frag));
      gl.linkProgram(prog);
    } catch (e) { console.error(e); setFailed(true); return; }
    gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, "p");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    const U: Record<string, WebGLUniformLocation | null> = {};
    for (const n of uniforms) U[n] = gl.getUniformLocation(prog, n);

    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let visible = true, raf = 0, clock = 0, last = performance.now();
    const io = new IntersectionObserver(([e]) => { visible = e.isIntersecting; }, { threshold: 0 });
    io.observe(canvas);
    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const p = live.current;
      const fixed = p.time !== undefined;
      if (!visible && !fixed) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      const sc = Math.max(0.2, Math.min(1, p.quality)) * dpr;
      const w = Math.max(2, Math.floor(canvas.clientWidth * sc));
      const h = Math.max(2, Math.floor(canvas.clientHeight * sc));
      if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
      gl.viewport(0, 0, w, h);
      const dt = (now - last) / 1000; last = now;
      if (!fixed && !reduce) clock += dt * p.speed;
      p.onFrame({ gl, U, t: fixed ? p.time! : clock, w, h, dyaw: drag.current.dyaw, dpitch: drag.current.dpitch, fixed });
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (fixed || reduce) { cancelAnimationFrame(raf); raf = 0; canvas.dataset.ready = "1"; }
    };
    raf = requestAnimationFrame(frame);
    (canvas as any).__redraw = () => { if (!raf) raf = requestAnimationFrame(frame); };
    return () => { cancelAnimationFrame(raf); io.disconnect(); };
  }, [frag]);

  React.useEffect(() => { (canvasRef.current as any)?.__redraw?.(); }, [redrawKey, time, quality]);

  const onDown = (e: React.PointerEvent) => {
    if (!interactive) return;
    drag.current.down = true; drag.current.x = e.clientX; drag.current.y = e.clientY;
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
  };
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current; if (!d.down) return;
    d.dyaw -= (e.clientX - d.x) * 0.008; d.dpitch += (e.clientY - d.y) * 0.006;
    d.x = e.clientX; d.y = e.clientY;
    (canvasRef.current as any)?.__redraw?.();
  };
  const onUp = () => { drag.current.down = false; };

  return (
    <div {...rest} style={{ position: "relative", isolation: "isolate", cursor: interactive ? "grab" : undefined, touchAction: interactive ? "pan-y" : undefined, ...style }}
      onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp}>
      {failed ? <div aria-hidden style={{ position: "absolute", inset: "20% 10%", borderRadius: "50%", background: "rgba(255,255,255,.75)", filter: "blur(30px)" }} /> :
        <canvas ref={canvasRef} aria-hidden style={{ position: "absolute", inset: 0, width: "100%", height: "100%", zIndex: behind ? -1 : 0, pointerEvents: "none" }} />}
      {children}
    </div>
  );
                 }
